def _validate_delimiter(delimiter):
    if not isinstance(delimiter, str) or len(delimiter) != 1 or delimiter in '"\n\r':
        raise ValueError("expected one delimiter character other than quote, LF or CR")


def parse_record(text, delimiter=","):
    """Split one delimited record into its fields."""
    _validate_delimiter(delimiter)
    fields = []
    pos = 0
    while True:
        if text.startswith('"', pos):
            pos += 1
            parts = []
            while True:
                end = text.find('"', pos)
                if end == -1:
                    raise ValueError("unterminated quoted field")
                parts.append(text[pos:end])
                pos = end + 1
                if not text.startswith('"', pos):
                    break
                parts.append('"')
                pos += 1
            fields.append("".join(parts))
        else:
            start = pos
            while pos < len(text) and text[pos] != delimiter:
                if text[pos] in '"\n\r':
                    raise ValueError("unexpected quote or line break in unquoted field")
                pos += 1
            fields.append(text[start:pos])

        if pos == len(text):
            return fields
        if text[pos] != delimiter:
            raise ValueError("expected a delimiter after the closing quote")
        pos += 1


def format_record(fields, delimiter=","):
    """Write fields as one delimited record."""
    _validate_delimiter(delimiter)
    try:
        iterator = iter(fields)
    except TypeError as exc:
        raise ValueError("expected an iterable of strings") from exc
    encoded = []
    for field in iterator:
        if not isinstance(field, str):
            raise ValueError("expected a string field")
        if (any(char in field for char in (delimiter, '"', '\n', '\r'))
                or field.startswith(" ") or field.endswith(" ")):
            field = '"' + field.replace('"', '""') + '"'
        encoded.append(field)
    if not encoded:
        raise ValueError("expected at least one field")
    return delimiter.join(encoded)
